SET NAMES utf8mb4;
-- ============================================================
-- V95__ingredient_family_and_alias.sql
-- 家庭私有食材 + 食材别名 + 运营收编
--   1) ingredient.family_id：NULL = 公共食材（只有运营能改）；非空 = 该家庭私有食材（别家不可见）
--   2) ingredient_alias：别名 -> 公共食材（alias 全局唯一；搜「土豆」能出「马铃薯」）
--   3) 别名种子：来自 scripts/recipe-fix/recipe_fix_map.py（由 scripts/ingredient-alias/gen_alias_sql.py 生成）
-- 幂等：information_schema 判断列/索引/表，种子 INSERT IGNORE（deploy.sh 每次部署都会跑）。
-- ============================================================

-- 1) ingredient.family_id
SET @c := (SELECT COUNT(*) FROM information_schema.COLUMNS
           WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'ingredient' AND COLUMN_NAME = 'family_id');
SET @s := IF(@c = 0,
    'ALTER TABLE ingredient ADD COLUMN family_id BIGINT NULL COMMENT ''所属家庭：NULL=公共食材，非空=该家庭私有'' AFTER name',
    'SELECT ''exists''');
PREPARE stmt FROM @s; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 创建时间（仅家庭新建的食材会写入，存量公共食材为 NULL；运营收编页「最早创建时间」用）
SET @c := (SELECT COUNT(*) FROM information_schema.COLUMNS
           WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'ingredient' AND COLUMN_NAME = 'create_time');
SET @s := IF(@c = 0,
    'ALTER TABLE ingredient ADD COLUMN create_time DATETIME NULL COMMENT ''创建时间（家庭新建食材才有）''',
    'SELECT ''exists''');
PREPARE stmt FROM @s; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @c := (SELECT COUNT(*) FROM information_schema.STATISTICS
           WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'ingredient' AND INDEX_NAME = 'idx_ingredient_family_name');
SET @s := IF(@c = 0,
    'ALTER TABLE ingredient ADD INDEX idx_ingredient_family_name (family_id, name)',
    'SELECT ''exists''');
PREPARE stmt FROM @s; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 2) 别名表
CREATE TABLE IF NOT EXISTS ingredient_alias (
  id            BIGINT       PRIMARY KEY AUTO_INCREMENT,
  alias         VARCHAR(64)  NOT NULL COMMENT '别名（已规整）',
  ingredient_id BIGINT       NOT NULL COMMENT '指向的公共食材 ingredient.id',
  create_time   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uk_ingredient_alias (alias),
  KEY idx_alias_ingredient (ingredient_id)
) COMMENT '食材别名（只指向公共食材）';

-- 3) 别名种子
-- 别名种子：317 条（由 scripts/ingredient-alias/gen_alias_sql.py 生成）
